window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2c51745180088873"]={"versions": [{"id": "FIG-2c51745180088873", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm für AUTOSAR Classic Basissoftware (BSW). Das Diagramm stellt die hierarchische Abhängigkeit und Einbindung (<code>#include</code>) zentraler Header-Dateien innerhalb des Kommunikationsstacks dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Communication related basic software modules</strong>: Übergreifende BSW-Module des Kommunikationsstacks (z. B. Can, Lin, Fr, Com, PduR), dargestellt als oberste Komponente.\n</li><li><strong>ComStack_Types.h</strong>: Zentrale Header-Datei für Typdefinitionen des Kommunikationsstacks; wird von den Kommunikationsmodulen inkludiert (<code>include</code>).\n</li><li><strong>Std_Types.h</strong>: AUTOSAR Standard-Typendefinitionen; wird von <code>ComStack_Types.h</code> inkludiert (<code>includes</code>).\n</li><li><strong>Platform_Types.h</strong>: Plattform- und compilerspezifische Basistypendefinitionen; wird von <code>Std_Types.h</code> inkludiert (<code>includes</code>).\n</li><li><strong>Compiler.h</strong>: Compiler-Abstraktionsmakros; wird ebenfalls von <code>Std_Types.h</code> inkludiert (<code>includes</code>).\n</li></ul>\n<p class=\"fig-p\">Alle Beziehungen sind als gerichtete Pfeile von der inkludierenden zur inkludierten Datei modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusionsverhältnis zur Kompilierzeit ohne Laufzeitsequenz. Der Präprozessor bindet transitiv <code>ComStack_Types.h</code> ein, wodurch <code>Std_Types.h</code> und nachfolgend parallel <code>Platform_Types.h</code> sowie <code>Compiler.h</code> aufgelöst werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Include-Hierarchie für Implementierer von BSW-Kommunikationsmodulen: Module des Kommunikationsstacks dürfen direkt <code>ComStack_Types.h</code> einbinden und erhalten dadurch transitiv Zugriff auf standardisierte Basistypen (<code>Std_Types.h</code>), Plattformtypen (<code>Platform_Types.h</code>) und Compiler-Abstraktionen (<code>Compiler.h</code>), ohne diese separat inkludieren zu müssen. Zyklische Abhängigkeiten sind ausgeschlossen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-314080619dc65021", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm für AUTOSAR Classic Basissoftware (BSW). Das Diagramm stellt die hierarchische Abhängigkeit und Einbindung (<code>#include</code>) zentraler Header-Dateien innerhalb des Kommunikationsstacks dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Communication related basic software modules</strong>: Übergreifende BSW-Module des Kommunikationsstacks (z. B. Can, Lin, Fr, Com, PduR), dargestellt als oberste Komponente.\n</li><li><strong>ComStack_Types.h</strong>: Zentrale Header-Datei für Typdefinitionen des Kommunikationsstacks; wird von den Kommunikationsmodulen inkludiert (<code>include</code>).\n</li><li><strong>Std_Types.h</strong>: AUTOSAR Standard-Typendefinitionen; wird von <code>ComStack_Types.h</code> inkludiert (<code>includes</code>).\n</li><li><strong>Platform_Types.h</strong>: Plattform- und compilerspezifische Basistypendefinitionen; wird von <code>Std_Types.h</code> inkludiert (<code>includes</code>).\n</li><li><strong>Compiler.h</strong>: Compiler-Abstraktionsmakros; wird ebenfalls von <code>Std_Types.h</code> inkludiert (<code>includes</code>).\n</li></ul>\n<p class=\"fig-p\">Alle Beziehungen sind als gerichtete Pfeile von der inkludierenden zur inkludierten Datei modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusionsverhältnis zur Kompilierzeit ohne Laufzeitsequenz. Der Präprozessor bindet transitiv <code>ComStack_Types.h</code> ein, wodurch <code>Std_Types.h</code> und nachfolgend parallel <code>Platform_Types.h</code> sowie <code>Compiler.h</code> aufgelöst werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Include-Hierarchie für Implementierer von BSW-Kommunikationsmodulen: Module des Kommunikationsstacks dürfen direkt <code>ComStack_Types.h</code> einbinden und erhalten dadurch transitiv Zugriff auf standardisierte Basistypen (<code>Std_Types.h</code>), Plattformtypen (<code>Platform_Types.h</code>) und Compiler-Abstraktionen (<code>Compiler.h</code>), ohne diese separat inkludieren zu müssen. Zyklische Abhängigkeiten sind ausgeschlossen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-72c916c9d4c16138", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm für AUTOSAR Classic Basissoftware (BSW). Das Diagramm stellt die hierarchische Abhängigkeit und Einbindung (<code>#include</code>) zentraler Header-Dateien innerhalb des Kommunikationsstacks dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Communication related basic software modules</strong>: Übergreifende BSW-Module des Kommunikationsstacks (z. B. Can, Lin, Fr, Com, PduR), dargestellt als oberste Komponente.\n</li><li><strong>ComStack_Types.h</strong>: Zentrale Header-Datei für Typdefinitionen des Kommunikationsstacks; wird von den Kommunikationsmodulen inkludiert (<code>include</code>).\n</li><li><strong>Std_Types.h</strong>: AUTOSAR Standard-Typendefinitionen; wird von <code>ComStack_Types.h</code> inkludiert (<code>includes</code>).\n</li><li><strong>Platform_Types.h</strong>: Plattform- und compilerspezifische Basistypendefinitionen; wird von <code>Std_Types.h</code> inkludiert (<code>includes</code>).\n</li><li><strong>Compiler.h</strong>: Compiler-Abstraktionsmakros; wird ebenfalls von <code>Std_Types.h</code> inkludiert (<code>includes</code>).\n</li></ul>\n<p class=\"fig-p\">Alle Beziehungen sind als gerichtete Pfeile von der inkludierenden zur inkludierten Datei modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusionsverhältnis zur Kompilierzeit ohne Laufzeitsequenz. Der Präprozessor bindet transitiv <code>ComStack_Types.h</code> ein, wodurch <code>Std_Types.h</code> und nachfolgend parallel <code>Platform_Types.h</code> sowie <code>Compiler.h</code> aufgelöst werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Include-Hierarchie für Implementierer von BSW-Kommunikationsmodulen: Module des Kommunikationsstacks dürfen direkt <code>ComStack_Types.h</code> einbinden und erhalten dadurch transitiv Zugriff auf standardisierte Basistypen (<code>Std_Types.h</code>), Plattformtypen (<code>Platform_Types.h</code>) und Compiler-Abstraktionen (<code>Compiler.h</code>), ohne diese separat inkludieren zu müssen. Zyklische Abhängigkeiten sind ausgeschlossen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2c51745180088873", "to": "FIG-314080619dc65021", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Am oberen Bildrand ist ein Fragment der Anforderungstextzeile „[COMTYPE001] The include file structure shall be...“ sichtbar angeschnitten.\n</li><li>Das eigentliche Diagramm der Include-Hierarchie und alle Modulboxen sind inhaltlich unverändert.\n</li></ul>"}, {"from": "FIG-314080619dc65021", "to": "FIG-72c916c9d4c16138", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Der Textabschnitt am oberen Bildrand ist horizontal verschoben bzw. zeigt nun das Textfragment „...he include file structure shall be as follows:“.\n</li><li>Die Diagrammelemente und Include-Beziehungen sind inhaltlich unverändert.\n</li></ul>"}]};
